/* The markup in index.html is fixed. Everything below is yours. */

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  color: #1b1f27;
  background: #fbfbfd;
  line-height: 1.5;
}

/* 1. --layout on :root, re-declared inside the breakpoint
   2. .site-nav  — flex row, space-between
   3. .nav-list  — flex row, no bullets, a gap
   4. #gallery   — three-column grid with a gap, no bullets
   5. .card-img  — block, max-width 100%, height auto
   6. @media (max-width: 640px) — stack the nav, collapse to one column */

solution.content:
:root {
  --layout: wide;
  --gap: 1.25rem;
  --ink: #1b1f27;
  --muted: #5a6270;
  --rule: #d7dce4;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  color: var(--ink);
  background: #fbfbfd;
  line-height: 1.5;
}

.site-header {
  border-bottom: 1px solid var(--rule);
  padding: 0.85rem 1.25rem;
  background: #fff;
}

.site-nav {
  display: flex;
  justify-content: space-between;
  gap: var(--gap);
  max-width: 64rem;
  margin: 0 auto;
}

.brand {
  font-weight: 700;
  text-decoration: none;
  color: inherit;
}

.nav-list {
  display: flex;
  flex-direction: row;
  gap: var(--gap);
  list-style: none;
  margin: 0;
  padding: 0;
}

.nav-list a { color: var(--muted); text-decoration: none; }

main {
  max-width: 64rem;
  margin: 0 auto;
  padding: 1.5rem 1.25rem 3rem;
}

h1 { font-size: 1.4rem; margin: 0 0 1.25rem; }

.gallery {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--gap);
  list-style: none;
  margin: 0;
  padding: 0;
}

.card {
  display: flex;
  flex-direction: column;
  border: 1px solid var(--rule);
  border-radius: 10px;
  overflow: hidden;
  background: #fff;
}

.card-img {
  display: block;
  width: 100%;
  max-width: 100%;
  height: auto;
}

.card h2 { font-size: 1rem; margin: 0.75rem 0.9rem 0.2rem; }

.card p { margin: 0 0.9rem 0.9rem; color: var(--muted); font-size: 0.9rem; }

@media (max-width: 640px) {
  :root { --layout: narrow; }

  .site-nav { flex-direction: column; }

  .nav-list { flex-direction: column; }

  .gallery { grid-template-columns: 1fr; }
}

